package com.lolfm.simulator;import java.util.*;
public final class ProgressionRewardResolver {public void awardExperience(PlayerState p,ExperienceSource src,int amount,int time){p.getProgressionState().awardExperience(src,amount,time);}public void awardKillExperience(PlayerState killer,List<PlayerState>assistants,int time){awardExperience(killer,ExperienceSource.KILL,ProgressionRuleConfig.KILL_XP,time);Set<PlayerState>seen=Collections.newSetFromMap(new IdentityHashMap<>());for(PlayerState a:assistants)if(a!=null&&a!=killer&&a.isAlive(time)&&seen.add(a))awardExperience(a,ExperienceSource.ASSIST,ProgressionRuleConfig.ASSIST_XP,time);}}
